// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        if (!ok) return;

        address currentOwner = c.owner();
        vm.assume(currentOwner == caller);

        vm.assume(caller != address(this));

        bool successCall;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            successCall = true;
        } catch {
            successCall = false;
        }

        assertTrue(!successCall);
    }
}
